const slots = $slots;
probe(Array.isArray(slots.values) && slots.values.length > 0, "the records must be a non-empty list");
const values = slots.values;
for (const value of values) {
  probe(Number.isInteger(value) && value > 0, "every record must be a positive whole number of crates");
}
probe(Number.isInteger(slots.threshold) && slots.threshold > 0, "the threshold must be a positive whole number of crates");
probe(Number.isInteger(slots.target) && slots.target > 0, "the target node must be a positive whole number of crates");
const kept = values.filter((value) => value < slots.threshold);
probe(kept.length > 0, "the filter must keep at least one record");
let target = slots.target;
while (target >= 1) {
  const edge = slots.edges.find(([from, to]) => from === target && to < slots.target);
  probe(edge !== undefined, "every node above the target must be connected to a lower node through one of the edges");
  target = edge[1];
}
return kept.length === 0 ? "No records below the threshold remain; path information is not computed." : "The records below the threshold form a path from " + slots.target + ".";

